<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SnapFrame — Capture, Create & Share What You Love</title>
<meta name="description" content="SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
<link href="https://cdn.jsdelivr.net/npm/remixicon@4.6.0/fonts/remixicon.css" rel="stylesheet">
<style>
/* ── Reset & Variables ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --black: #000000;
  --purple: #7638FA;
  --orange: #FF7A00;
  --purple-light: #F3EEFF;
  --orange-light: #FFF5EB;
  --gray-50: #FAFAFA;
  --gray-100: #F5F5F5;
  --gray-200: #E8E8E8;
  --gray-300: #D4D4D4;
  --gray-400: #A3A3A3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --gray-900: #171717;
  --white: #FFFFFF;
  --gradient-hero: linear-gradient(135deg, #7638FA 0%, #A855F7 40%, #FF7A00 100%);
  --gradient-card: linear-gradient(135deg, #F3EEFF 0%, #FFF5EB 100%);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.10);
  --max-width: 1200px;
  --header-height: 72px;
}

html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: var(--white);
  color: var(--black);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
a { text-decoration: none; color: inherit; }
img { display: block; max-width: 100%; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul { list-style: none; }

/* ── Utility ── */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 28px; border-radius: var(--radius-full); font-weight: 600;
  font-size: 15px; transition: all 0.2s ease; white-space: nowrap;
}
.btn-primary { background: var(--black); color: var(--white); }
.btn-primary:hover { background: var(--gray-800); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
.btn-outline { background: var(--white); color: var(--black); border: 2px solid var(--gray-200); }
.btn-outline:hover { border-color: var(--black); transform: translateY(-1px); }
.btn-store {
  background: var(--black); color: var(--white); padding: 12px 24px;
  border-radius: var(--radius-md); font-size: 14px; gap: 10px;
}
.btn-store:hover { background: var(--gray-800); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-store i { font-size: 22px; }

.section-label {
  display: inline-block; font-size: 13px; font-weight: 700;
  letter-spacing: 0.08em; text-transform: uppercase; color: var(--purple);
  margin-bottom: 12px;
}

/* ── Header ── */
.header {
  position: fixed; top: 0; left: 0; right: 0; height: var(--header-height);
  background: rgba(255,255,255,0.92); backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  z-index: 1000; border-bottom: 1px solid var(--gray-200);
}
.header .container { display: flex; align-items: center; justify-content: space-between; height: 100%; }
.header-logo {
  font-size: 24px; font-weight: 800; letter-spacing: -0.02em;
  background: var(--gradient-hero); -webkit-background-clip: text;
  -webkit-text-fill-color: transparent; background-clip: text;
}
.header-nav { display: flex; align-items: center; gap: 32px; }
.header-nav a { font-size: 15px; font-weight: 500; color: var(--gray-700); transition: color 0.2s; }
.header-nav a:hover { color: var(--black); }
.header-actions { display: flex; align-items: center; gap: 12px; }
.header-login {
  padding: 10px 24px; border-radius: var(--radius-full); font-weight: 600;
  font-size: 14px; background: var(--purple-light); color: var(--purple);
  transition: all 0.2s;
}
.header-login:hover { background: var(--purple); color: var(--white); }

/* Hamburger */
.hamburger {
  display: none; flex-direction: column; gap: 5px; width: 28px;
  padding: 4px 0; cursor: pointer; z-index: 1001;
}
.hamburger span {
  display: block; height: 2.5px; background: var(--black);
  border-radius: 2px; transition: all 0.3s ease; transform-origin: center;
}
.hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

.mobile-overlay {
  display: none; position: fixed; inset: 0; background: rgba(0,0,0,0.5);
  z-index: 998; opacity: 0; transition: opacity 0.3s;
}
.mobile-overlay.active { display: block; opacity: 1; }
.mobile-nav {
  display: none; position: fixed; top: 0; right: -320px; width: 300px;
  height: 100vh; background: var(--white); z-index: 999; padding: 100px 32px 32px;
  transition: right 0.3s ease; flex-direction: column; gap: 24px;
  box-shadow: -8px 0 32px rgba(0,0,0,0.15);
}
.mobile-nav.active { right: 0; }
.mobile-nav a { font-size: 18px; font-weight: 600; color: var(--gray-800); }
.mobile-nav .header-login {
  display: inline-flex; justify-content: center; margin-top: 8px;
}

/* ── Hero ── */
.hero {
  padding: calc(var(--header-height) + 80px) 0 100px;
  position: relative; overflow: hidden;
  background: var(--gray-50);
}
.hero::before {
  content: ''; position: absolute; top: -50%; left: -20%; width: 70%;
  height: 200%; background: radial-gradient(ellipse, rgba(118,56,250,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero::after {
  content: ''; position: absolute; bottom: -30%; right: -10%; width: 60%;
  height: 160%; background: radial-gradient(ellipse, rgba(255,122,0,0.06) 0%, transparent 60%);
  pointer-events: none;
}
.hero .container { position: relative; z-index: 1; }
.hero-content { max-width: 720px; }
.hero h1 {
  font-size: clamp(36px, 6vw, 64px); font-weight: 900; line-height: 1.08;
  letter-spacing: -0.025em; margin-bottom: 24px;
  background: linear-gradient(135deg, var(--black) 0%, var(--purple) 60%, var(--orange) 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero p {
  font-size: clamp(16px, 2vw, 19px); color: var(--gray-600);
  line-height: 1.6; margin-bottom: 36px; max-width: 560px;
}
.hero-cta {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 16px 36px; background: var(--purple); color: var(--white);
  font-size: 17px; font-weight: 700; border-radius: var(--radius-full);
  transition: all 0.2s;
}
.hero-cta:hover { background: #6528E8; transform: translateY(-2px); box-shadow: 0 8px 28px rgba(118,56,250,0.35); }
.hero-cta i { font-size: 20px; transition: transform 0.2s; }
.hero-cta:hover i { transform: translateX(4px); }
.hero-visual {
  position: absolute; right: -60px; top: 50%; transform: translateY(-50%);
  width: 480px; height: 480px; border-radius: 50%;
  background: var(--gradient-hero); opacity: 0.06; pointer-events: none;
  filter: blur(80px);
}

/* ── Section Shared ── */
.section { padding: 100px 0; }
.section-gray { background: var(--gray-50); }

/* ── Features ── */
.features-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 80px;
  align-items: center;
}
.features-text h2 {
  font-size: clamp(28px, 4vw, 40px); font-weight: 800; line-height: 1.15;
  letter-spacing: -0.02em; margin-bottom: 20px;
}
.features-text p {
  font-size: 17px; color: var(--gray-600); line-height: 1.7;
  margin-bottom: 28px;
}
.features-link {
  display: inline-flex; align-items: center; gap: 6px; font-size: 16px;
  font-weight: 600; color: var(--purple); transition: gap 0.2s;
}
.features-link:hover { gap: 10px; }
.features-link i { font-size: 18px; }
.features-visual {
  display: grid; grid-template-columns: 1fr 1fr; gap: 16px;
}
.feature-card {
  background: var(--white); border-radius: var(--radius-lg); padding: 28px;
  box-shadow: var(--shadow-sm); transition: all 0.3s;
}
.feature-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.feature-card:nth-child(1) { border-top: 4px solid var(--purple); }
.feature-card:nth-child(2) { border-top: 4px solid var(--orange); margin-top: 24px; }
.feature-card:nth-child(3) { border-top: 4px solid #EC4899; }
.feature-card:nth-child(4) { border-top: 4px solid #8B5CF6; margin-top: 24px; }
.feature-card i { font-size: 28px; margin-bottom: 12px; }
.feature-card:nth-child(1) i { color: var(--purple); }
.feature-card:nth-child(2) i { color: var(--orange); }
.feature-card:nth-child(3) i { color: #EC4899; }
.feature-card:nth-child(4) i { color: #8B5CF6; }
.feature-card h4 { font-size: 15px; font-weight: 700; margin-bottom: 4px; }
.feature-card p { font-size: 13px; color: var(--gray-500); line-height: 1.5; }

/* ── Safety ── */
.safety-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 80px;
  align-items: center;
}
.safety-visual {
  background: linear-gradient(135deg, #F0FDF4 0%, #ECFEFF 50%, #FEF3C7 100%);
  border-radius: var(--radius-xl); padding: 48px; position: relative; overflow: hidden;
}
.safety-visual-inner {
  display: grid; grid-template-columns: 1fr 1fr; gap: 16px;
}
.safety-icon-card {
  background: var(--white); border-radius: var(--radius-md); padding: 24px;
  text-align: center; box-shadow: var(--shadow-sm);
}
.safety-icon-card i { font-size: 32px; color: #10B981; margin-bottom: 8px; }
.safety-icon-card span { font-size: 13px; font-weight: 600; color: var(--gray-700); }
.safety-text h2 {
  font-size: clamp(28px, 4vw, 40px); font-weight: 800; line-height: 1.15;
  letter-spacing: -0.02em; margin-bottom: 20px;
}
.safety-text p {
  font-size: 17px; color: var(--gray-600); line-height: 1.7;
  margin-bottom: 28px;
}
.safety-link {
  display: inline-flex; align-items: center; gap: 6px; font-size: 16px;
  font-weight: 600; color: #10B981; transition: gap 0.2s;
}
.safety-link:hover { gap: 10px; }

/* ── Creators ── */
.creators-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 80px;
  align-items: center;
}
.creators-text h2 {
  font-size: clamp(28px, 4vw, 40px); font-weight: 800; line-height: 1.15;
  letter-spacing: -0.02em; margin-bottom: 20px;
}
.creators-text p {
  font-size: 17px; color: var(--gray-600); line-height: 1.7;
  margin-bottom: 28px;
}
.creators-link {
  display: inline-flex; align-items: center; gap: 6px; font-size: 16px;
  font-weight: 600; color: var(--orange); transition: gap 0.2s;
}
.creators-link:hover { gap: 10px; }
.creators-visual {
  background: linear-gradient(135deg, #FFF5EB 0%, #FEF3C7 50%, #FFF1F2 100%);
  border-radius: var(--radius-xl); padding: 48px; position: relative; overflow: hidden;
}
.creator-stat { text-align: center; }
.creator-stat-number {
  font-size: 48px; font-weight: 900; letter-spacing: -0.02em;
  background: linear-gradient(135deg, var(--orange) 0%, #EF4444 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.creator-stat-label { font-size: 14px; font-weight: 600; color: var(--gray-600); }
.creators-visual-inner { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; }

/* ── Tagline Banner ── */
.tagline-banner {
  background: var(--gradient-hero); padding: 56px 0; text-align: center;
  position: relative; overflow: hidden;
}
.tagline-banner::before {
  content: ''; position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.06'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
