}
.news-header a:hover { text-decoration: underline; }

.news-carousel-wrapper { position: relative; }
.news-carousel {
  display: flex; gap: 20px; overflow-x: auto; scroll-snap-type: x mandatory;
  scroll-behavior: smooth; -webkit-overflow-scrolling: touch;
  padding-bottom: 16px; scrollbar-width: none;
}
.news-carousel::-webkit-scrollbar { display: none; }
.news-card {
  flex: 0 0 auto; width: 340px; scroll-snap-align: start;
  background: var(--white); border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm); overflow: hidden; transition: all 0.3s;
  cursor: pointer;
}
.news-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.news-card-thumb {
  height: 180px; position: relative; overflow: hidden;
}
.news-card:nth-child(1) .news-card-thumb { background: linear-gradient(135deg, #7638FA 0%, #A855F7 100%); }
