<script>
(function() {
  var hamburger = document.getElementById('hamburger');
  var overlay = document.getElementById('mobileOverlay');
  var mobileNav = document.getElementById('mobileNav');
  var mobileLinks = mobileNav.querySelectorAll('a');
  var isOpen = false;

  function closeMenu() {
    isOpen = false;
    hamburger.classList.remove('active');
    overlay.classList.remove('active');
    mobileNav.classList.remove('active');
    document.body.style.overflow = '';
  }

  function openMenu() {
    isOpen = true;
    hamburger.classList.add('active');
    overlay.classList.add('active');
    mobileNav.classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  hamburger.addEventListener('click', function() {
    isOpen ? closeMenu() : openMenu();
  });

  overlay.addEventListener('click', closeMenu);

  mobileLinks.forEach(function(link) {
    link.addEventListener('click', closeMenu);
  });

  // Carousel controls
  var carousel = document.getElementById('newsCarousel');
  var prevBtn = document.getElementById('carouselPrev');
  var nextBtn = document.getElementById('carouselNext');

  function getScrollAmount() {
    var card = carousel.querySelector('.news-card');
    return card ? card.offsetWidth + 20 : 340; // card width + gap
  }

  prevBtn.addEventListener('click', function() {
    carousel.scrollBy({ left: -getScrollAmount(), behavior: 'smooth' });
  });

  nextBtn.addEventListener('click', function() {
    carousel.scrollBy({ left: getScrollAmount(), behavior: 'smooth' });
  });

  // Touch swipe for mobile (prevent page scroll when swiping carousel)
  var touchStartX = 0;
  carousel.addEventListener('touchstart', function(e) {
    touchStartX = e.touches[0].clientX;
  }, { passive: true });

  carousel.addEventListener('touchmove', function(e) {
    var diff = touchStartX - e.touches[0].clientX;
    if (Math.abs(diff) > 10) {
      e.stopPropagation();
    }
  }, { passive: false });
})();
</script>

